// Pre-computes everything the hosted static demo needs, using the real scanner.
// Output: apps/web/public/demo-data/** (git-ignored, regenerated by `pnpm build:demo`).
//
// Scans, offline Queue/Signature compatibility checks and recorded Cache Isolation
// results are all produced by the same code the desktop app and CLI run. Absolute
// local paths are rewritten to /demo/<fixture> so nothing about the build machine leaks.
import fs from 'node:fs';
import path from 'node:path';
import {
  scanRepository,
  loadQueueCompatibilityConfig,
  runQueueCompatibilityCheck,
  loadSignatureCompatibilityConfig,
  runSignatureCompatibilityCheck,
  parseCacheIsolationResult,
  loadCacheIsolationConfig,
} from '@stackfold/scanner';

// Run from apps/web (see the build:demo-data script).
const webRoot = process.cwd();
const repoRoot = path.resolve(webRoot, '../..');
const outRoot = path.join(webRoot, 'public/demo-data');

const FIXTURES = [
  ['sample-ecommerce-app', 'Sample E-Commerce Store'],
  ['sample-monorepo-platform', 'Multi-Package Monorepo Platform'],
  ['preview-fence-vercel-supabase', 'PreviewFence Environment Risk'],
  ['tx-escape-prisma', 'TxEscape Transaction Risk'],
  ['scopepatch-idtrace', 'ScopePatch and IDTrace Guardrails'],
  ['cache-isolation-vulnerable', 'Cache Isolation Security Lab'],
  ['signature-compatibility-vulnerable', 'Signature Compatibility Mismatch'],
  ['signature-compatibility-passing', 'Signature Compatibility Passing'],
  ['queue-compatibility-failing', 'Queue Compatibility Historical Mismatch'],
  ['queue-compatibility-passing', 'Queue Compatibility Passing'],
];

const rootFor = id => path.join(repoRoot, 'fixtures', id);

function sanitize(value, id) {
  const root = rootFor(id);
  const json = JSON.stringify(value).split(root).join(`/demo/${id}`).split(repoRoot).join('/demo');
  if (/\/Users\/|\/home\/[a-z]|C:\\\\Users/.test(json)) {
    throw new Error(`Local path leaked into demo data for ${id}`);
  }
  return json;
}

function write(rel, id, value) {
  const file = path.join(outRoot, rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, sanitize(value, id));
}

fs.rmSync(outRoot, { recursive: true, force: true });
const manifest = { generatedAt: new Date().toISOString(), scans: [], security: {} };

for (const [id, name] of FIXTURES) {
  const root = rootFor(id);
  const t = Date.now();
  const result = await scanRepository({ rootPath: root, projectName: name, useCache: false, maxFiles: 15000 });
  write(`scan/${id}.json`, id, {
    success: true,
    graph: result.graph,
    durationMs: result.durationMs,
    scannedFilesCount: result.scannedFilesCount,
    diagnostics: result.diagnostics,
    fromCache: false,
    canonicalPath: root,
  });
  manifest.scans.push(id);
  console.log(`scan  ${id.padEnd(36)} ${result.graph.nodes.length} nodes  ${Date.now() - t}ms`);

  // Queue Compatibility: offline and deterministic, so the "live" result is precomputed faithfully.
  try {
    const { config, configPath } = loadQueueCompatibilityConfig(root);
    const live = await runQueueCompatibilityCheck(config, { rootPath: root });
    write(`security/queue-compatibility/${id}.json`, id, { success: true, result: live, source: `precomputed:fixture:${id}`, configPath });
    (manifest.security.queue ??= []).push(id);
  } catch {}

  if (id.startsWith('signature-compatibility-')) try {
    const { config, configPath } = loadSignatureCompatibilityConfig(root);
    // Same synthetic, fixture-only secret the web API route injects for bundled demos.
    const env = { ...process.env, [config.secretEnv]: process.env[config.secretEnv] ?? 'sig-synthetic-demo-secret' };
    const live = await runSignatureCompatibilityCheck(config, { env });
    write(`security/signature-compatibility/${id}.json`, id, { success: true, result: live, source: `precomputed:fixture:${id}`, configPath });
    (manifest.security.signature ??= []).push(id);
  } catch {}

  // Cache Isolation needs two live Chromium sessions: ship the recorded result only.
  try {
    const { configPath } = loadCacheIsolationConfig(root);
    const recorded = parseCacheIsolationResult(fs.readFileSync(path.join(root, '.stackfold/cache-isolation-results.json'), 'utf8'));
    write(`security/cache-isolation/${id}.json`, id, { success: true, result: recorded, source: `recorded:fixture:${id}`, configPath });
    (manifest.security.cache ??= []).push(id);
  } catch {}
}

fs.writeFileSync(path.join(outRoot, 'manifest.json'), JSON.stringify(manifest, null, 2));
console.log(`\nDemo data written to ${path.relative(repoRoot, outRoot)}`);
